import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, vec4, mix, step, uniform, positionLocal, smoothstep, float } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, Shape, ExtrudeGeometry, PlaneGeometry, Color, DirectionalLight, AmbientLight, DoubleSide } = ctx.THREE;

  const root = new Group();
  root.name = config.id ?? 'gradient-cta';

  // ---- palette (verbatim from spec) ----
  const COL = {
    background: '#0b0b10',
    surface: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    g0: '#ff4450',
    g1: '#ff2a38',
    g2: '#c1121f',
  };

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const labelItem = items.find((i) => i.role === 'cta-label') ?? { text: 'BEGIN COMMISSION' };
  const captionItem = items.find((i) => i.role === 'caption') ?? { text: 'NO DEPOSIT REQUIRED' };

  // ---- STAGE backdrop plane (~7x6 @ z=-2.5) with vertical gradient ----
  const bgGeo = new PlaneGeometry(7, 6);
  const bgMat = new MeshBasicNodeMaterial();
  {
    const vy = uv().y;
    const top = vec3(0.086, 0.086, 0.102);   // #16161d-ish surface
    const bot = vec3(0.043, 0.043, 0.063);   // #0b0b10 background
    bgMat.colorNode = mix(bot, top, smoothstep(0.0, 1.0, vy));
  }
  const backdrop = new Mesh(bgGeo, bgMat);
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);

  // ---- button geometry: rounded-rect extruded with bevel/chamfer ----
  const W = 2.6, H = 0.68, R = 0.08;
  function roundedRectShape(w, h, r) {
    const s = new Shape();
    const x = -w / 2, y = -h / 2;
    s.moveTo(x + r, y);
    s.lineTo(x + w - r, y);
    s.quadraticCurveTo(x + w, y, x + w, y + r);
    s.lineTo(x + w, y + h - r);
    s.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
    s.lineTo(x + r, y + h);
    s.quadraticCurveTo(x, y + h, x, y + h - r);
    s.lineTo(x, y + r);
    s.quadraticCurveTo(x, y, x + r, y);
    return s;
  }
  const btnGeo = new ExtrudeGeometry(roundedRectShape(W, H, R), {
    depth: 0.03,
    bevelEnabled: true,
    bevelThickness: 0.03,
    bevelSize: 0.02,
    bevelSegments: 2,
    curveSegments: 12,
  });
  btnGeo.center();

  const btnMat = new MeshStandardNodeMaterial();
  btnMat.roughness = 0.5;
  btnMat.metalness = 0.35;
  if ('clearcoat' in btnMat) btnMat.clearcoat = 0.22;

  const emissiveBoost = uniform(1.6);

  // engineered vertical gradient with hard seam @50% face height, zero blur
  {
    const vy = uv().y;
    const c0 = vec3(1.0, 0.267, 0.314);   // #ff4450
    const c1 = vec3(1.0, 0.165, 0.22);    // #ff2a38
    const c2 = vec3(0.757, 0.071, 0.122); // #c1121f
    // 0.0 -> 0.55 : c0->c1 ; 0.55 -> 1.0 : c1->c2, with a hard seam at 0.5
    const lower = mix(c0, c1, smoothstep(0.0, 0.55, vy));
    const upper = mix(c1, c2, smoothstep(0.55, 1.0, vy));
    const grad = mix(lower, upper, step(0.55, vy));
    // hard seam line at 50% (0.01 unit -> approx a narrow band in uv)
    const seam = smoothstep(0.503, 0.5, vy).mul(smoothstep(0.497, 0.5, vy)).mul(4.0);
    const face = mix(grad, c2.mul(0.6), seam.clamp(0.0, 1.0));
    btnMat.colorNode = vec4(face, 1.0);
    // perimeter emissive channel in accent
    const nx = uv().x.sub(0.5).abs().mul(2.0);
    const ny = uv().y.sub(0.5).abs().mul(2.0);
    const edge = smoothstep(0.9, 0.985, nx.max(ny));
    btnMat.emissiveNode = vec3(1.0, 0.165, 0.22).mul(edge).mul(emissiveBoost);
  }

  const button = new Mesh(btnGeo, btnMat);
  button.position.set(0, 0.12, 0);
  root.add(button);

  // ---- node-local lighting: rim/accent + ambient fill ----
  const ambient = new AmbientLight(new Color(COL.paper), 0.4);
  root.add(ambient);
  const key = new DirectionalLight(new Color('#ffffff'), 1.2);
  key.position.set(-2.5, 3, 3);
  root.add(key);
  const rim = new DirectionalLight(new Color(COL.accent), 0.9);
  rim.position.set(3, -2, 2);
  root.add(rim);

  // ---- contact shadow plane ----
  const shGeo = new PlaneGeometry(W * 1.25, H * 1.4);
  const shMat = new MeshBasicNodeMaterial();
  shMat.transparent = true;
  {
    const c = uv().sub(0.5);
    const d = c.length().mul(2.0);
    const a = smoothstep(1.0, 0.0, d).mul(0.35);
    shMat.colorNode = vec4(vec3(0.0), a);
  }
  const shadow = new Mesh(shGeo, shMat);
  shadow.position.set(0, 0.12 - 0.36, -0.05);
  root.add(shadow);

  // ---- text: label + caption ----
  const label = ctx.fontAtlas.createText(String(labelItem.text ?? 'BEGIN COMMISSION'), {
    fontSize: 40,
    color: COL.paper,
    align: 'center',
    letterSpacingPx: 3,
  });
  label.position.set(0, 0.12, 0.06);
  root.add(label);

  const caption = ctx.fontAtlas.createText(String(captionItem.text ?? 'NO DEPOSIT REQUIRED'), {
    fontSize: 18,
    color: COL.paper,
    align: 'center',
    letterSpacingPx: 3,
  });
  caption.position.set(0, 0.12 - H / 2 - 0.25, 0.02);
  root.add(caption);

  // ---- apply configured primitives (if any) ----
  const primHandles = [];
  const primList = config.cinematicPrimitives ?? [];
  for (const p of primList) {
    const fn = ctx.primitives?.[p.name];
    if (fn) {
      const h = fn(button, p.params ?? {});
      if (h) primHandles.push(h);
    }
  }

  // ---- mount motion: weighted-settle 1.04 -> 1.0 ----
  const tl = gsap.timeline();
  root.scale.setScalar(1.04);
  tl.to(root.scale, { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' });

  // ---- interaction handlers ----
  let hoverTween, pressTween;
  root.userData.handlers = {
    hover: () => {
      hoverTween?.kill();
      hoverTween = gsap.timeline();
      hoverTween.to(button.position, { z: 0.06, duration: 0.18, ease: 'power2.out' }, 0);
      hoverTween.to(emissiveBoost, { value: 2.2, duration: 0.18, ease: 'power2.out' }, 0);
    },
    unhover: () => {
      hoverTween?.kill();
      hoverTween = gsap.timeline();
      hoverTween.to(button.position, { z: 0, duration: 0.18, ease: 'power2.out' }, 0);
      hoverTween.to(emissiveBoost, { value: 1.6, duration: 0.18, ease: 'power2.out' }, 0);
    },
    click: () => {
      pressTween?.kill();
      pressTween = gsap.timeline();
      pressTween.to(root.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out(2)' });
      pressTween.to(shadow.scale, { x: 0.85, y: 0.85, duration: 0.12, ease: 'power2.out' }, 0);
      pressTween.to(root.scale, { x: 1, y: 1, z: 1, duration: 0.3, ease: 'power4.out' });
      pressTween.to(shadow.scale, { x: 1, y: 1, duration: 0.3, ease: 'power4.out' }, '<');
      ctx.emit('navigate', { to: 'hub-pricing' });
    },
  };

  // ---- cleanup ----
  root.userData.cleanup = () => {
    tl.kill();
    hoverTween?.kill();
    pressTween?.kill();
    for (const h of primHandles) h.cleanup?.();
    bgGeo.dispose();
    bgMat.dispose();
    btnGeo.dispose();
    btnMat.dispose();
    shGeo.dispose();
    shMat.dispose();
    label.traverse?.((o) => { o.geometry?.dispose?.(); o.material?.dispose?.(); });
    caption.traverse?.((o) => { o.geometry?.dispose?.(); o.material?.dispose?.(); });
  };

  return root;
}
